function qdToc(ctx) {
  var bid = native.match(ctx.book.bookUrl, 'book/(\\d+)', 1);
  if (!bid) throw new Error('无法从书籍地址取得书号：' + ctx.book.bookUrl);
  var url = 'https://wxapp.qidian.com/api/book/categoryV2?bookId=' + bid;
  var res = http.get(url);
  if (!res.ok) throw new Error('目录接口请求失败：HTTP ' + res.status);
  var payload = res.json();
  if (!payload || payload.code !== 0 || !payload.data || !payload.data.vs) throw new Error('目录接口返回异常');
  var chapters = [];
  payload.data.vs.forEach(function (volume) {
    if (volume.vN) chapters.push({ title: volume.vN, isVolume: true });
    (volume.cs || []).forEach(function (item) {
      chapters.push({
        title: item.cN,
        url: 'https://m.qidian.com/chapter/' + bid + '/' + item.id + '/',
        isVip: item.sS === 0,
        tag: (item.uT || '') + (item.cnt ? ' · ' + item.cnt + '字' : '')
      });
    });
  });
  if (!chapters.length) throw new Error('目录为空，站点可能调整了目录接口');
  return chapters;
}

// 榜单（2026-11-14 修复）：起点已不再通过 /category/ 下发 _csrfToken，
// 而 majax/rank/* 要求「URL 参数与 Cookie 里的 _csrfToken 相同」——
// 缺 token 时服务端直接回 {"code":1,"msg":"失败"}，宿主就显示「发现接口返回失败：失败」。
// 做法：每次请求自造一个 uuid，同时放进参数与 Cookie 头（实测 code:0，20 条/页，可翻页）。
function qdRank(ctx) {
  var t = uuid();
  var url = String(ctx.url || '');
  if (url.indexOf('_csrfToken=') >= 0) {
    url = url.replace(/_csrfToken=[^&]*/, '_csrfToken=' + t);
  } else {
    url += (url.indexOf('?') >= 0 ? '&' : '?') + '_csrfToken=' + t;
  }
  var res = http.get(url, { headers: {
    'User-Agent': 'Mozilla/5.0 (Linux; U; Android 13; zh-cn; MI 11) AppleWebKit/537.36 (KHTML, like Gecko) Version/4.0 Chrome/120 Mobile Safari/537.36',
    'Referer': 'https://m.qidian.com/',
    'Cookie': '_csrfToken=' + t,
    'Accept': 'application/json, text/plain, */*'
  } });
  if (!res.ok) { throw new Error('榜单请求失败：HTTP ' + res.status); }
  var j = res.json();
  if (!j || Number(j.code) !== 0) { throw new Error('榜单接口返回：' + ((j && j.msg) || '空')); }
  var list = ((j.data || {}).records) || [];
  var out = [];
  for (var i = 0; i < list.length; i++) {
    var it = list[i] || {};
    var kind = [];
    if (it.cat) { kind.push(String(it.cat)); }
    if (it.subCat) { kind.push(String(it.subCat)); }
    out.push({
      name: String(it.bName || ''),
      author: String(it.bAuth || ''),
      kind: kind.join(','),
      intro: String(it.desc || ''),
      wordCount: it.cnt == null ? '' : String(it.cnt),
      lastChapter: it.lastVUCname == null ? '' : String(it.lastVUCname),
      coverUrl: 'https://bookcover.yuewen.com/qdbimg/349573/' + it.bid,
      bookUrl: 'https://m.qidian.com/book/' + it.bid + '/'
    });
  }
  if (!out.length) {
    if (Number(ctx.page || 1) > 1) { return []; }
    throw new Error('榜单无数据');
  }
  return out;
}

/* ================= 段评 / 本章说（v3, 2026-11-14） =================
 * 站点：起点移动版 m.qidian.com 的 /webcommon/* 接口，免登录。
 * 实测要点：
 *  1) 三个接口都要 _csrfToken，且「URL 参数」与「Cookie 里的」必须是同一个值
 *     —— 只放参数会 403 Forbidden（实测），所以两者用同一个常量。
 *  2) 固定 token 可长期复用：5 组请求（summary/段评两页/章末）全部 200 且 code=0。
 *  3) reviewsummary4m 只给「热门段落」（这正是起点自己挂气泡的规则），
 *     每项 { paragraphId, textCount, isHotSegment, isHotComment }；
 *     paragraphId=-1 是章末评论（不进气泡），气泡行号 = paragraphId - 1
 *     （引擎行号口径：按 \n 切、跳空行、0 基）。
 *  4) reviewlist4m 支持 page 翻页（size=12/页），故页面取前 2 页合并去重。
 *  5) 章末 getchapterendcomments 返回 DataList + TotalCount（DataList 项字段名首字母大写）。
 * 若站点某天失效：把 QD_CM_TOK 换成新的 uuid（参数与 Cookie 同步即可）。
 */
var QD_CM_TOK = '00000000-0000-4000-8000-000000000001';
var QD_CM_UA = 'Mozilla/5.0 (Linux; Android 12; Pixel 5) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/120 Mobile Safari/537.36';

function qdCmTok() { return QD_CM_TOK; }
function qdCmUA() { return QD_CM_UA; }
function qdCmCookie() { return '_csrfToken=' + QD_CM_TOK; }
function qdCmIds(chapUrl) {
  var m = String(chapUrl || '').match(/chapter\/(\d+)\/(\d+)/);
  return m ? { bid: m[1], cid: m[2] } : { bid: '', cid: '' };
}
function qdCmUrl(chapUrl, path, params) {
  var ids = qdCmIds(chapUrl);
  var q = ['bookId=' + ids.bid];
  if (path.indexOf('reviewlist4m') >= 0) { q.push('chapterId=' + ids.cid); }
  else { q.push('chapterId=' + ids.cid); }
  for (var k in (params || {})) { q.push(k + '=' + encodeURIComponent(params[k])); }
  q.push('_csrfToken=' + QD_CM_TOK);
  return 'https://m.qidian.com' + path + '?' + q.join('&');
}
function qdCmSumUrl(chapUrl) { return qdCmUrl(chapUrl, '/webcommon/chapterreview/reviewsummary4m', {}); }
function qdCmListUrl(chapUrl, paragraphId, page) { return qdCmUrl(chapUrl, '/webcommon/chapterreview/reviewlist4m', { paragraphId: paragraphId, page: page }); }
function qdCmEndUrl(chapUrl) { return qdCmUrl(chapUrl, '/webcommon/review/getchapterendcomments', {}); }
/* 统计 → { 行号: 条数 } */
function qdCmCounts(stats) {
  var out = {};
  try {
    var list = (stats && stats.data && stats.data.list) || [];
    for (var i = 0; i < list.length; i++) {
      var it = list[i] || {};
      var pid = Number(it.paragraphId);
      var cnt = Number(it.textCount || 0);
      if (!(pid >= 1) || !(cnt > 0)) { continue; }
      out[pid - 1] = cnt;
    }
  } catch (e) {}
  return out;
}
function qdCmItems(resp) { try { return (resp && resp.data && resp.data.list) || []; } catch (e) { return []; } }
function qdCmTotal(resp, fallback) {
  try { var n = Number((resp && resp.data && resp.data.total) || 0); if (n > 0) { return n; } } catch (e) {}
  return Number(fallback || 0);
}
function qdCmMerge(a, b) {
  var out = [], seen = {};
  var lists = [qdCmItems(a), qdCmItems(b)];
  for (var l = 0; l < lists.length; l++) {
    for (var i = 0; i < lists[l].length; i++) {
      var x = lists[l][i] || {};
      var key = String(x.reviewId || x.cbid || ((x.userId || '') + '|' + x.content));
      if (seen[key]) { continue; }
      seen[key] = 1; out.push(x);
    }
  }
  return out;
}
function qdCmWhen(ts) { try { return native.formatDate(Number(ts), 'yyyy-MM-dd HH:mm'); } catch (e) { return ''; } }
function qdEndItems(resp) { try { return (resp && resp.data && resp.data.DataList) || []; } catch (e) { return []; } }
function qdEndTotal(resp, fallback) {
  try { var n = Number((resp && resp.data && resp.data.TotalCount) || 0); if (n > 0) { return n; } } catch (e) {}
  return Number(fallback || 0);
}

/* 多路合并（fetch 上限 3 个请求 → 段评取 3 页） */
function qdCmMergeN() {
  var out = [], seen = {};
  for (var a = 0; a < arguments.length; a++) {
    var arr = qdCmItems(arguments[a]);
    for (var i = 0; i < arr.length; i++) {
      var x = arr[i] || {};
      var key = String(x.reviewId || x.cbid || ((x.userId || '') + '|' + x.content));
      if (seen[key]) { continue; }
      seen[key] = 1; out.push(x);
    }
  }
  return out;
}

/* 注入页面的数据瘦身：只留渲染要用的字段（减小序列化/解析与内存开销） */
function qdCmSlim(items) {
  var out = [];
  for (var i = 0; i < (items || []).length; i++) {
    var x = items[i] || {};
    var rp = [], list = x.replyList || [];
    for (var k = 0; k < list.length && k < 3; k++) {
      var y = list[k] || {};
      rp.push([String(y.nickName || ''), String(y.content || '').slice(0, 120)]);
    }
    out.push({ u: String(x.nickName || '读者'), t: String(x.content || '').slice(0, 300),
               l: Number(x.likeCount || 0), ip: String(x.ipAddress || ''), r: rp });
  }
  return out;
}
function qdEndSlim(items) {
  var out = [];
  for (var i = 0; i < (items || []).length; i++) {
    var x = items[i] || {};
    out.push({ u: String(x.UserName || '读者'), t: String(x.Content || '').slice(0, 300),
               l: Number(x.AgreeAmount || 0), ip: String(x.IpLocation || ''), c: Number(x.ReviewCount || 0) });
  }
  return out;
}
